// Spezza i blocchi di testo lunghi in paragrafi leggibili (~2-4 frasi ciascuno).
// Le frasi vengono accumulate finché il paragrafo non supera ~380 caratteri:
// il guard di lunghezza evita spezzature strane su abbreviazioni (es. "art. 14").
const toParagraphs = (text: string): string[] => {
  const sentences = text.match(/[^.!?]+[.!?]+["»']?(\s+|$)/g) ?? [text];
  const paras: string[] = [];
  let cur = "";
  for (const s of sentences) {
    cur += s;
    if (cur.length > 380) {
      paras.push(cur.trim());
      cur = "";
    }
  }
  if (cur.trim()) paras.push(cur.trim());
  return paras;
};

const FadeIn = ({ children, delay = 0, className = "" }: { children: React.ReactNode; delay?: number; className?: string }) => {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-80px" });
  return (
    <motion.div ref={ref} initial={{ opacity: 0, y: 50 }} animate={isInView ? { opacity: 1, y: 0 } : {}} transition={{ duration: 0.8, delay, ease: [0.16, 1, 0.3, 1] }} className={className}>
      {children}
    </motion.div>
  );
};

